using namespace std;

void Bubble_sort(int data[],int n)
{

	for(int i = 0;i < n-1;i++)
	{
		for(int j = 0;j < n-1-i;j++)
		{
			if(data[j] > data[j+1])
			{
				swap(data[j],data[j+1]);
			}
		}

	}
}

bool Search(int data[],int n,int &target)
{
	int min,mid,max;
	min = 0;
	max = n-1;
	while(min <= max)
	{
		mid = (min+max)/2;
		if(data[mid] < target)
		{
			min = mid+1;
		}else if(data[mid] == target)
		{
			return 1;
		}
		else
		{
			max = mid-1;
		}
	}
	return 0;
}

